content = content.replace("                        try:\n                            raw_text = run_async_task(scraper.run_direct_scrape(target_url))\n                            st.success(\"Direct scrape completed successfully!\")", "                        try:\n                            if not st.session_state.get('scrape_completed'):\n                                raw_text = run_async_task(scraper.run_direct_scrape(target_url))\n                                st.session_state.cached_raw_text = raw_text\n                                record_id = save_scrape_record(\n                                    url=target_url,\n                                    mode=\"Direct Scrape\",\n                                    raw_text=raw_text,\n                                    summary=f\"Direct text scrape of {target_url}\"\n                                )\n                                st.session_state.cached_record_id = record_id\n                            raw_text = st.session_state.cached_raw_text\n                            record_id = st.session_state.cached_record_id\n                            st.success(\"Direct scrape completed successfully!\")")

